examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchAiInlineDiff(
    segments = segments,
    onAccept = { id -> segments = MonarchAiDiffSegment.resolve(segments, id, accept = true) },
    onReject = { id -> segments = MonarchAiDiffSegment.resolve(segments, id, accept = false) },
)

examples.setupTemplate:
var segments by remember {
    mutableStateOf(
        MonarchAiDiffSegment.diffWords(
            {{before}},
            {{after}},
        ),
    )
}

examples.setup:
var segments by remember {
    mutableStateOf(
        MonarchAiDiffSegment.diffWords(
            "Our team meets every week to review the plan. We will ship the new flow in May, and collect feedback after.",
            "Our team meets every Monday to review the roadmap. We will ship the redesigned flow in June, and collect feedback after launch.",
        ),
    )
}

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchAiInlineDiff(
    segments = segments,
    onAccept = { id -> segments = MonarchAiDiffSegment.resolve(segments, id, accept = true) },
    onReject = { id -> segments = MonarchAiDiffSegment.resolve(segments, id, accept = false) },
)

@OptIn(ExperimentalMonarchApi::class)
MonarchAiInlineDiff(
    segments = listOf(
        MonarchAiDiffSegment(MonarchAiDiffSegmentType.Equal, "Ships on "),
        MonarchAiDiffSegment(MonarchAiDiffSegmentType.Delete, "Friday"),
        MonarchAiDiffSegment(MonarchAiDiffSegmentType.Insert, "Monday"),
    ),
    showNavigation = false,
)
